def solve(record):
    """
    Read the audit ledger from record['record_0'], accumulate points per
    entrant (registration order = first-appearance order), then return the
    entrant names sorted by descending total points. Ties keep registration
    order. Returns [] for empty/missing input.
    """
    x = record.get('record_0') if isinstance(record, dict) else None
    if not x:
        return []

    def _to_num(v):
        try:
            return float(v)
        except (TypeError, ValueError):
            return 0.0

    # Ledger may contain multiple entries per entrant; accumulate totals
    # while preserving registration (first-appearance) order.
    totals = {}
    for row in x:
        try:
            name = row[0]
            pts = row[1]
        except (TypeError, IndexError, KeyError):
            continue
        if name not in totals:
            totals[name] = 0.0
        totals[name] += _to_num(pts)

    # Stable sort by descending points; ties retain registration order.
    ordered = sorted(totals.items(), key=lambda kv: -kv[1])
    return [name for name, _pts in ordered]
