def solve(record):
    """
    Fold [item, signed quantity] transactions from record['record_2']
    into an object of net quantities per item.

    Item codes come from a keyboard with a sticky caps lock, so the
    capitalization of the codes as recorded is unreliable; the canonical
    identity of a code is its case-insensitive form (lowercase).
    """
    x = record.get('record_2') if isinstance(record, dict) else None
    if not x:
        return {}

    net = {}

    def normalize(code):
        # Sticky caps lock scrambles letter case; canonicalize to lowercase.
        return ''.join(ch.lower() if ch.isalpha() else ch for ch in str(code))

    def to_number(q):
        # Signed quantity: keep native numeric types, coerce numeric strings.
        if isinstance(q, str):
            s = q.strip()
            try:
                return int(s)
            except ValueError:
                return float(s)
        if isinstance(q, bool):
            return int(q)
        if isinstance(q, float) and q.is_integer():
            return int(q)
        return q

    for entry in x:
        item, qty = entry[0], entry[1]
        key = normalize(item)
        value = to_number(qty)
        net[key] = to_number(net.get(key, 0) + value) if key in net else value

    return net
```

